from pathlib import Path
import json,numpy as np
HERE=Path(__file__).resolve().parent;RUNS=HERE.parents[1]/'runs'
z=np.load(HERE/'bin-picking/od-pipeline-source.npz');data={key:z[key]for key in z.files};t=data['time_s'];q=data['command'].copy();meta=json.load(open(RUNS/'native-roas-table-bin-under30-capture01/pipeline-results.json'));inds=[meta['dof_names'].index(f'right_arm_fr3v2_joint{j}')for j in range(1,8)];plan=json.load(open(RUNS/'native-roas-table-od-plan07/od-plan.json'));route=next(row for row in plan['routes']if row['label']=='large_OD_descend');path=np.array(route['waypoints'])[4:];a,b=6.3,10.3;mask=(t>=a)&(t<=b);weights=np.array([max(.05,np.linalg.norm(B-A))for A,B in zip(path[:-1],path[1:])]);knots=np.r_[0,np.cumsum(weights)];knots=knots/knots[-1]*(b-a);elapsed=t[mask]-a;seg=np.clip(np.searchsorted(knots,elapsed,side='right')-1,0,len(path)-2);u=np.clip((elapsed-knots[seg])/(knots[seg+1]-knots[seg]),0,1);h=u**3*(10-15*u+6*u*u);q[np.ix_(np.flatnonzero(t<a),inds)]=path[0];q[np.ix_(np.flatnonzero(mask),inds)]=path[seg]+(path[seg+1]-path[seg])*h[:,None];data['command']=q;np.savez_compressed(HERE/'bin-picking/od-pipeline-short-hover.npz',**data);print('PREPARED_HOVER_M',.13*(1-4/11))
